import { debugGetAllActionTemplates, getCurrentState } from "./game/mainSimulationLogic";
import { getAvailableChoices, isChoiceTemplate } from "./UIfacade/actionFacade";
  const activablesState = getCurrentState().getInternalStateObject().activables;
  let result = 'ACTION TEMPLATES';
  debugGetAllActionTemplates()
    .forEach(actTemplate => {
      result += '<br/><br/>' + JSON.stringify(actTemplate) + '<br/>actTemplate activable : ' + JSON.stringify(activablesState[actTemplate.uid]);

      if (isChoiceTemplate(actTemplate)) {
        actTemplate.choices.forEach(choice => result += '<br/>choice activable : ' + JSON.stringify(activablesState[choice.uid]))
        result += '<br/>' + (getAvailableChoices(actTemplate).length > 0 ? 'has available choice' : 'no available choice');
        }
    });
  result;
